const lockProductTokenMint = `-- name: LockProductTokenMint :exec
SELECT pg_advisory_xact_lock(
    1970958452,
    hashtext($1::uuid::text || ':' || $2::uuid::text)
)
`

type LockProductTokenMintParams struct {
	UserID    uuid.UUID `json:"user_id"`
	ProductID uuid.UUID `json:"product_id"`
}

// Serializes one (user, product) pair's mints (the D15 cap: at most 10 active tokens per
// user per product). Under READ COMMITTED two concurrent mints would each count against
// their own snapshot and both pass a cap check that was true when each looked; the
// minting handler therefore runs, in ONE transaction: this lock, then
// CountActiveProductTokensForUserProduct, then CreateProductToken. The same reasoning as
// store.HostedProvisionLockClass (migrate.go).
//
// Two-int advisory lock: class 1970958452 = 0x757A7074 ("uzpt"), the value of
// store.ProductTokenMintLockClass in migrate.go, distinct from every other class
// constant there; TestProductTokenMintLockClassMatchesSQL pins this literal to it. The
// two-int space is disjoint from the one-bigint space RegistrationLockKey /
// SettingsMutationLockKey use. The objid is hashtext of the
// (user, product) pair, so two unrelated pairs can collide: a moment of contention,
// never a correctness problem. XACT-scoped: released on commit or rollback, so it must
// run on a transaction-bound Queries (on a bare pool it would release immediately).
func (q *Queries) LockProductTokenMint(ctx context.Context, arg LockProductTokenMintParams) error {
	_, err := q.db.Exec(ctx, lockProductTokenMint, arg.UserID, arg.ProductID)
	return err
}

const revokeAllProductTokens = `-- name: RevokeAllProductTokens :exec
UPDATE product_tokens SET revoked = true WHERE user_id = $1 AND grant_id IS NULL AND NOT revoked
`

// The panic button's product half (D8): revoke every un-revoked MANUAL product token of one
// user (grant_id IS NULL). Access tokens of an OAuth grant are not swept here: the revoke-all
// handler revokes every live grant first through revokeGrantLocked (grant lock, then the grant's
// tokens). The filter is defence in depth: the per-user lock (LockOAuthUserGrants) already
// serializes grant creation with Revoke all, and token exchanges wait on the grant rows Revoke
// all holds, so no grant can appear mid-sweep; the filter keeps a plain sweep from ever revoking
// a grant's access token without its grant lock (PRD #1910 D8). Called by the existing revoke-all handler (POST
// /api/me/cli-tokens/revoke-all, handler.RevokeAllCLITokens) in the SAME transaction as
// RevokeAllCLITokens, so the button revokes both token kinds or neither. Idempotent, and scoped
// to $1.
func (q *Queries) RevokeAllProductTokens(ctx context.Context, userID uuid.UUID) error {
	_, err := q.db.Exec(ctx, revokeAllProductTokens, userID)
	return err
}

